}", "newString": "/// Analyzes a union annotation against the actually returned types.
///
/// Returns `Some(covered_variants)` when the annotation is misleadingly wide,
/// i.e. the function only ever returns values belonging to a strict subset of
/// the union's variants. `covered_variants` holds the annotation variants that
/// are actually exercised, so a narrower suggestion can be rendered from them.
///
/// Returns `None` when the annotation is not misleadingly wide, or when the
/// union contains a variant (`any`, `unknown`, `never`) that makes narrowing
/// meaningless.
fn analyze_union_widening(annotated: &Type, returns: &[Type]) -> Option<Vec<Type>> {
    let variants: Vec<Type> = annotated.flattened_union_variants().collect();
    if variants.len() < 2 {
        return None;
    }

    // `any`/`unknown` absorb every other variant, and `never` carries no
    // values, so no narrowing is meaningful in either case.
    if variants.iter().any(|variant| {
        matches!(
            &**variant,
            TypeData::AnyKeyword
                | TypeData::UnknownKeyword
                | TypeData::Unknown
                | TypeData::NeverKeyword
        )
    }) {
        return None;
    }

    // Literal variants that are absorbed by a primitive also present in the
    // union collapse into that primitive (e.g. `"a" | string` is just
    // `string`). Drop them before analyzing coverage.
    let mut effective: Vec<Type> = Vec::new();
    for variant in &variants {
        if is_absorbed_literal(variant, &variants) {
            continue;
        }
        if effective.iter().any(|kept| types_match(kept, variant)) {
            continue;
        }
        effective.push(variant.clone());
    }

    // A union that collapses to a single type needs no narrowing.
    if effective.len() < 2 {
        return None;
    }

    // Every returned value must belong to some annotation variant. Otherwise
    // the annotation isn't merely wider than the implementation, and flagging
    // would risk a false positive.
    let all_returns_covered = returns.iter().all(|ret| {
        variants
            .iter()
            .any(|variant| types_match(variant, ret) || is_nonunion_wider(variant, ret))
    });
    if !all_returns_covered {
        return None;
    }

    let covered: Vec<Type> = effective
        .iter()
        .filter(|variant| union_variant_is_covered(variant, returns))
        .cloned()
        .collect();

    // Misleading only when a strict, non-empty subset of the variants is used.
    if covered.is_empty() || covered.len() == effective.len() {
        return None;
    }

    Some(covered)
}

/// Whether a union variant is actually exercised by the returned types.
///
/// A `boolean` variant is only considered covered when both `true` and `false`
/// are returned (or `boolean` itself), because a function returning only `true`
/// hides the `false` case that the annotation promises.
fn union_variant_is_covered(variant: &Type, returns: &[Type]) -> bool {
    if matches!(&**variant, TypeData::Boolean) {
        let has_boolean = returns
            .iter()
            .any(|ret| matches!(&**ret, TypeData::Boolean));
        let has_true = returns.iter().any(|ret| ret.is_boolean_literal(true));
        let has_false = returns.iter().any(|ret| ret.is_boolean_literal(false));
        return has_boolean || (has_true && has_false);
    }

    returns
        .iter()
        .any(|ret| types_match(variant, ret) || is_nonunion_wider(variant, ret))
}

