/// Builds a suggestion like `"a" | "b"` or `boolean` from the covered union
/// variants. Returns `None` when a variant cannot be rendered or the rendered
/// suggestion would exceed [`MAX_DESCRIPTION_LENGTH`].
fn build_union_suggestion(covered: &[Type]) -> Option<String> {
    let mut parts: Vec<String> = Vec::with_capacity(covered.len());
    for variant in covered {
        parts.push(render_union_variant(variant)?);
    }
    if parts.is_empty() {
        return None;
    }
    let text = parts.join(" | ");
    if text.len() > MAX_DESCRIPTION_LENGTH {
        return None;
    }
    Some(text)
}

/// Renders a single union variant as TypeScript source text.
fn render_union_variant(variant: &Type) -> Option<String> {
    match &**variant {
        TypeData::String => Some("string".to_string()),
