        TypeData::Boolean => Some("boolean".to_string()),
        TypeData::BigInt => Some("bigint".to_string()),
        TypeData::Null => Some("null".to_string()),
        TypeData::Undefined => Some("undefined".to_string()),
        TypeData::Literal(literal) => match literal.as_ref() {
